export function evaluate({ inputs, time, seed, state }) {
  const launchSpeed = inputs.launchSpeed;
  const gravity = inputs.gravity;
  const apexTime = launchSpeed / gravity;
  const apexHeight = (launchSpeed * launchSpeed) / (2 * gravity);
  const t = time;
  const tossedHeight = launchSpeed * t - 0.5 * gravity * t * t;
  const tossedVelocity = launchSpeed - gravity * t;
  const tossedAcceleration = -gravity;

  let dropHeight = apexHeight;
  let dropVelocity = 0;
  let dropAcceleration = 0;
  if (t >= apexTime) {
    const dt = t - apexTime;
    dropHeight = apexHeight - 0.5 * gravity * dt * dt;
    dropVelocity = -gravity * dt;
    dropAcceleration = -gravity;
  }

  let stateToss = "At launch";
  if (t > 0 && t < apexTime) stateToss = "Rising";
  else if (Math.abs(t - apexTime) < 0.05) stateToss = "At the top";
  else if (t > apexTime && tossedHeight > 0) stateToss = "Falling";
  else if (t >= apexTime && tossedHeight <= 0) stateToss = "At launch height";

  let stateDrop = "Held in place";
  if (Math.abs(t - apexTime) < 0.05) stateDrop = "Just released";
  else if (t > apexTime && dropHeight > 0) stateDrop = "Falling together";
  else if (t >= apexTime && dropHeight <= 0) stateDrop = "At launch height";

  const hScale = 120 / 2.2;
  const baseY = 360;
  const tossX = 200;
  const dropX = 440;

  const yToss = baseY - tossedHeight * hScale;
  const yDrop = baseY - dropHeight * hScale;

  const objects = [];
  objects.push(...sdk.panel({ x: 60, y: 50, w: 260, h: 350, title: "Toss lane", state: stateToss, id: "lane.toss" }));
  objects.push(...sdk.panel({ x: 340, y: 50, w: 260, h: 350, title: "Drop lane", state: stateDrop, id: "lane.drop" }));

  objects.push(sdk.circle("ball.toss", tossX, yToss, 28, { role: "output" }));
  objects.push(sdk.circle("ball.drop", dropX, yDrop, 28, { role: "output" }));

  objects.push(...sdk.vector("vec.v.toss", { x: tossX - 20, y: yToss }, { value: tossedVelocity, direction: "up" }, { scale: 15, label: "v" }));
  objects.push(...sdk.vector("vec.a.toss", { x: tossX + 20, y: yToss }, { value: tossedAcceleration, direction: "up" }, { scale: 15, label: "a" }));

  objects.push(...sdk.vector("vec.v.drop", { x: dropX - 20, y: yDrop }, { value: dropVelocity, direction: "up" }, { scale: 15, label: "v" }));
  objects.push(...sdk.vector("vec.a.drop", { x: dropX + 20, y: yDrop }, { value: dropAcceleration, direction: "up" }, { scale: 15, label: "a" }));

  objects.push(...sdk.callout(tossX + 45, yToss - 20, [`v: ${sdk.format(tossedVelocity)} m/s`, `a: ${sdk.format(tossedAcceleration)} m/s^2`], { id: "callout.toss" }));
  objects.push(...sdk.callout(dropX + 45, yDrop - 20, [`v: ${sdk.format(dropVelocity)} m/s`, `a: ${sdk.format(dropAcceleration)} m/s^2`], { id: "callout.drop" }));

  if (t >= apexTime) {
    objects.push(sdk.gate("gate", dropX, baseY - apexHeight * hScale, { open: true, label: "Apex gate" }));
  } else {
    objects.push(sdk.gate("gate", dropX, baseY - apexHeight * hScale, { open: false, label: "Apex gate" }));
  }

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "tossedVelocity", value: tossedVelocity },
        { id: "tossedAcceleration", value: tossedAcceleration },
        { id: "dropVelocity", value: dropVelocity },
        { id: "dropAcceleration", value: dropAcceleration }
      ]
    },
    quantities: {
      launchSpeed,
      gravity,
      apexTime,
      apexHeight,
      tossedVelocity,
      tossedAcceleration,
      tossedHeight,
      dropVelocity,
      dropAcceleration,
      dropHeight
    }
  };
}
